//! The base IRI that relative IRIs generated by term maps resolve against.

use std::fmt;

use oxrdf::NamedNode;

use crate::Error;

/// The base IRI of the R2RML execution environment (R2RML §4).
///
/// R2RML §11.2 prepends it to a generated string that is not an absolute
/// IRI. This is plain string concatenation, not the reference resolution of
/// RFC 3986 §5.2 (R2RML §4 says so explicitly): `../x` becomes
/// `<base>../x`, `?q` becomes `<base>?q`.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct BaseIri(String);

impl BaseIri {
    /// R2RML §4: the base IRI must be a valid IRI. It must also be
    /// absolute, since prepending it has to give absolute IRIs. A query
    /// (`?`), a fragment (`#`) or a missing trailing `/` are allowed, as
    /// R2RML only advises against them.
    pub fn new(iri: &str) -> Result<Self, Error> {
        NamedNode::new(iri).map_err(|e| Error::InvalidBaseIri(format!("{iri:?}: {e}")))?;
        Ok(Self(iri.to_owned()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for BaseIri {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

/// Whether `value` starts with a scheme and `:` (RFC 3987 §2.2:
/// `scheme = ALPHA *( ALPHA / DIGIT / "+" / "-" / "." )`).
///
/// This is how the engine tells an absolute IRI from a relative one when it
/// generates IRIs (R2RML §11.2), because SQL can test it on a column too
/// (see [`SCHEME_REGEX`]), which keeps comparisons in SQL consistent with the
/// terms built from rows. A value with a scheme that is not a valid IRI is a
/// data error; R2RML would first try the base IRI in front of it, which only
/// differs for values such as `http://host:port/` with a non-numeric port.
/// A fragment does not make an IRI relative: the W3C test R2RMLTC0019a
/// expects `http://example.com/ns#Jhon` from a column as it is.
pub fn has_scheme(value: &str) -> bool {
    let Some((scheme, _)) = value.split_once(':') else {
        return false;
    };
    let mut chars = scheme.chars();
    chars.next().is_some_and(|c| c.is_ascii_alphabetic())
        && chars.all(|c| c.is_ascii_alphanumeric() || matches!(c, '+' | '-' | '.'))
}

/// A PostgreSQL regular expression that matches exactly the strings for
/// which [`has_scheme`] is true.
pub const SCHEME_REGEX: &str = "^[A-Za-z][-+.0-9A-Za-z]*:";

/// The IRI generated from `value`, the natural lexical form of a column or
/// a rendered template of a term map with term type `rr:IRI` (R2RML §11.2):
/// `value` itself when it has a scheme, otherwise `base` followed by
/// `value`. Either must be a valid IRI, or it is a data error.
pub fn generated_iri(value: &str, base: Option<&BaseIri>) -> Result<NamedNode, Error> {
    if has_scheme(value) {
        return NamedNode::new(value).map_err(|e| {
            Error::InvalidTerm(format!(
                "{value:?} is not a valid IRI (R2RML data error): {e}"
            ))
        });
    }
    let Some(base) = base else {
        return Err(Error::InvalidTerm(format!(
            "{value:?} is a relative IRI and no base IRI is set (R2RML data error); set one \
             with --base-iri, V12N_BASE_IRI or base_iri under [mapping]"
        )));
    };
    let resolved = format!("{base}{value}");
    NamedNode::new(&resolved).map_err(|e| {
        Error::InvalidTerm(format!(
            "{value:?} resolves against the base IRI to {resolved:?}, which is not a valid IRI \
             (R2RML data error): {e}"
        ))
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn base() -> BaseIri {
        BaseIri::new("http://example.com/base/").unwrap()
    }

    fn resolve(value: &str) -> String {
        generated_iri(value, Some(&base())).unwrap().into_string()
    }

    #[test]
    fn base_iri_must_be_an_absolute_iri() {
        assert!(BaseIri::new("http://example.com/base/").is_ok());
        // R2RML only advises against these.
        assert!(BaseIri::new("http://example.com/ns#").is_ok());
        assert!(BaseIri::new("http://example.com/base").is_ok());
        assert!(BaseIri::new("urn:x-base:").is_ok());
        for bad in [
            "",
            "base/",
            "/base/",
            "http://example.com/a b/",
            "http://[x/",
        ] {
            let err = BaseIri::new(bad).unwrap_err();
            assert!(matches!(err, Error::InvalidBaseIri(_)), "{bad}: {err}");
        }
    }

    #[test]
    fn has_scheme_follows_the_rfc_3987_scheme_rule() {
        for yes in [
            "http://example.com/",
            "urn:isbn:1",
            "a+b-c.d:x",
            "mailto:",
            "x:",
            "H:",
        ] {
            assert!(has_scheme(yes), "{yes}");
        }
        for no in [
            "", "Bob", ":x", "1http:x", "a_b:x", "a b:x", "/x:y", "%41:x", "한:x", "Bob/x:y",
        ] {
            assert!(!has_scheme(no), "{no}");
        }
    }

    #[test]
    fn generated_iri_keeps_absolute_values() {
        assert_eq!(
            resolve("http://example.com/ns#Jhon"),
            "http://example.com/ns#Jhon"
        );
        assert_eq!(resolve("urn:x:1"), "urn:x:1");
    }

    #[test]
    fn generated_iri_prepends_the_base_by_concatenation() {
        assert_eq!(resolve("Carlos"), "http://example.com/base/Carlos");
        assert_eq!(resolve(""), "http://example.com/base/");
        // Not RFC 3986 §5.2 resolution: dot segments, a leading slash, a
        // query or a fragment are kept where they are.
        assert_eq!(resolve("../x"), "http://example.com/base/../x");
        assert_eq!(resolve("./x/../y"), "http://example.com/base/./x/../y");
        assert_eq!(resolve("/x"), "http://example.com/base//x");
        assert_eq!(resolve("?q=1"), "http://example.com/base/?q=1");
        assert_eq!(resolve("#f"), "http://example.com/base/#f");
        assert_eq!(resolve("a?b#c"), "http://example.com/base/a?b#c");
        // A colon after a non-scheme character is part of a path.
        assert_eq!(resolve("a_b:c"), "http://example.com/base/a_b:c");
        let hash = BaseIri::new("http://example.com/ns#").unwrap();
        assert_eq!(
            generated_iri("Bob", Some(&hash)).unwrap().as_str(),
            "http://example.com/ns#Bob"
        );
    }

    #[test]
    fn generated_iri_reports_data_errors() {
        let error = |value: &str, base: Option<&BaseIri>| match generated_iri(value, base) {
            Err(Error::InvalidTerm(message)) => message,
            other => panic!("{value}: {other:?}"),
        };
        // No base IRI: the message names the setting.
        let message = error("Bob", None);
        assert!(message.contains("V12N_BASE_IRI"), "{message}");
        assert!(message.contains("--base-iri"), "{message}");
        assert!(
            error("Juan Daniel", Some(&base())).contains("http://example.com/base/Juan Daniel")
        );
        // A value with a scheme is never resolved, even when invalid.
        assert!(error("http://host:port/", Some(&base())).contains("not a valid IRI"));
        assert!(error("http://a b/", None).contains("not a valid IRI"));
    }
}
